// Generates table_gen.go and testdata/icu_golden.json from the ICU that ships with Node.
//   cd apps/api/internal/rules/collate && source ~/.nvm/nvm.sh && nvm use && node testdata/gen.mjs
// The oracle is `new Intl.Collator('en-US')`, the collation packages/data's localeCompare uses today.
// Output depends on the ICU/CLDR version; the versions are recorded in both generated files.
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const dflt = new Intl.Collator('en-US')
const base = new Intl.Collator('en-US', { sensitivity: 'base' })
const accent = new Intl.Collator('en-US', { sensitivity: 'accent' })
const info = `ICU ${process.versions.icu}, Unicode ${process.versions.unicode}, CLDR ${process.versions.cldr}, Node ${process.version}`

// Latin: C0 controls aside, ASCII, Latin-1, Latin Extended-A/B, IPA-free, Latin Extended Additional.
const ranges = [[0x09, 0x0d], [0x20, 0x7e], [0xa0, 0x24f], [0x1e00, 0x1eff]]
// Letters that ICU expands to two letters: handled in Go, kept out of the single-letter classes.
const expansions = new Map([[0xdf, 'ss'], [0x1e9e, 'ss'], [0xc6, 'AE'], [0xe6, 'ae'], [0x152, 'OE'], [0x153, 'oe'], [0x132, 'IJ'], [0x133, 'ij'], [0x149, 'ʼn']])
const cps = []
for (const [lo, hi] of ranges) for (let c = lo; c <= hi; c++) cps.push(c)
const marks = (s) => [...s.normalize('NFD')].filter((ch) => /\p{M}/u.test(ch)).length
const keep = cps.filter((c) => {
  const ch = String.fromCodePoint(c)
  if (expansions.has(c) || expansions.has([...ch.normalize('NFD')][0].codePointAt(0))) return false // Ǽ is Æ + acute
  if (dflt.compare(ch, '') === 0) return false // ignorable
  // From Latin Extended-B on: only accented letters (a base + marks); stroke, hook, digraph and ligature letters have odd places.
  if (c >= 0x180 && ch.normalize('NFD') === ch) return false
  const k = [...ch.normalize('NFKD')].filter((x) => !/\p{M}/u.test(x))
  return k.length === 1 // drops fractions, ligatures, digraphs
})
keep.sort((a, b) => dflt.compare(String.fromCodePoint(a), String.fromCodePoint(b)) || a - b)

let p = 0, s = 0, t = 0, prev = null
const rows = []
for (const c of keep) {
  const ch = String.fromCodePoint(c)
  if (prev === null) { p = 1; s = 1; t = 1 }
  else if (base.compare(prev, ch) !== 0) { p++; s = 1; t = 1 }
  else if (accent.compare(prev, ch) !== 0) { s++; t = 1 }
  else if (dflt.compare(prev, ch) !== 0) { t++ }
  rows.push([c, p, s, t])
  prev = ch
}
const compose = []
for (const c of keep) {
  const d = [...String.fromCodePoint(c).normalize('NFD')]
  if (d.length === 2 && /\p{M}/u.test(d[1]) && !/\p{M}/u.test(d[0]) && keep.includes(d[0].codePointAt(0)))
    compose.push([d[0].codePointAt(0), d[1].codePointAt(0), c])
}
compose.sort((a, b) => a[0] - b[0] || a[1] - b[1])

const hex = (n) => '0x' + n.toString(16).toUpperCase().padStart(4, '0')
let go = `// Code generated by testdata/gen.mjs; DO NOT EDIT.
// Source: ${info}.

package collate

// entries maps a character to its ICU en-US collation weights: primary (base letter), secondary
// (accent) and tertiary (case). Sorted by rune.
var entries = []entry{\n`
for (const [c, pp, ss, tt] of [...rows].sort((a, b) => a[0] - b[0])) go += `\t{${hex(c)}, ${pp}, ${ss}, ${tt}},\n`
go += `}\n\n// expansions are letters ICU sorts as two letters.\nvar expansions = map[rune]string{\n`
for (const [c, v] of [...expansions].sort((a, b) => a[0] - b[0])) go += `\t${hex(c)}: ${JSON.stringify(v)},\n`
go += `}\n\n// compositions joins a base letter and a combining mark into the precomposed letter, so decomposed\n// (NFD) input compares the same as composed input.\nvar compositions = []composition{\n`
for (const [b, m, c] of compose) go += `\t{${hex(b)}, ${hex(m)}, ${hex(c)}},\n`
go += `}\n`
writeFileSync(join(here, '..', 'table_gen.go'), go)

// ---- golden: strings in ICU order, plus sampled pairs ----
let seed = 20261115
const rnd = () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let x = Math.imul(seed ^ (seed >>> 15), 1 | seed); x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x; return ((x ^ (x >>> 14)) >>> 0) / 4294967296 }
const pick = (a) => a[Math.floor(rnd() * a.length)]
const pool = rows.map((r) => String.fromCodePoint(r[0]))
const words = ['Ana', 'ana', 'ANA', 'Ánå', 'Zoë', 'ZOE', 'zoe', "O'Brien", 'Obrien', 'Smith-Jones', 'Smith Jones', 'SmithJones', 'Jean Luc', 'Jean-Luc', 'Émile', 'Emile', 'emile', 'Ángel', 'Angel', 'ångel', 'Žofia', 'Zofia', 'Çelik', 'Celik', 'Øyvind', 'Oyvind', 'Ana2', 'Ana10', 'ana maria', 'Ana Maria', 'Ana-Maria', 'Ana  Maria', 'José', 'Jose', 'josé', 'Nuñez', 'Nunez', 'Dalton', 'Dexter', 'Gab', 'Jasper', 'Maria Steph', 'Mikee Abellana', 'Łukasz', 'Lukasz', 'Đorđe', 'Dorde', 'İpek', 'Ipek', 'ıpek', 'Ñ', 'n', 'N']
const set = new Set(words)
while (set.size < 2500) {
  const n = 1 + Math.floor(rnd() * 6)
  let w = ''
  for (let i = 0; i < n; i++) w += rnd() < 0.55 ? pick('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('')) : pick(pool)
  set.add(w)
}
const all = [...set].filter((w) => w.length > 0)
all.sort((a, b) => dflt.compare(a, b))
const strings = all.filter((w, i) => i === 0 || dflt.compare(all[i - 1], w) !== 0) // ties removed
const pairs = []
for (let i = 0; i < 4000; i++) { const a = pick(strings), b = pick(strings); pairs.push([a, b, Math.sign(dflt.compare(a, b))]) }
writeFileSync(join(here, 'icu_golden.json'), JSON.stringify({ icu: info, sorted: strings, pairs }, null, 0) + '\n')
console.log(info, 'entries', rows.length, 'compose', compose.length, 'strings', strings.length)
